module.exports = [{"title":"দ্বিতীয় খণ্ড","desc":"সন্তদের সেই দেশটি"},{"title":"সুবিশাল ক্ষার সমতটে","desc":""},{"title":"","desc":"সুবৃহৎ উত্তর আমেরিকা মহাদেশের মধ্যবর্তী অঞ্চলে একটা অনুর্বর আর বীভৎস মরুভূমি আছে। সভ্যতার অগ্রগতি বহু বছর ধরে সেখানে ঠোক্কর খেয়ে আটকে গিয়েছে। সিয়েরা নেভাদা থেকে নেব্রাস্কা আর উত্তরের ইয়োলোস্টোন নদী থেকে দক্ষিণের কলোরাডো পর্যন্ত বিস্তীর্ণ ঊষর-অঞ্চলে বিরাজ করছে কেবল কবরের নীরবতা। বিকট এই মরুভূমির সর্বত্র একরূপে বিরাজিত নয় প্রকৃতি। কোথাও  বরফ মুকুট পরা মেঘালয় পর্বতমালা। কোথাও অন্ধকার মৃত্যু-বিষাদে টংকারময় ধু-ধু উপত্যকা। খাঁজকাটা কিরিচের মতো গভীর গিরিখাদ ভেদ করে কোথাও বজ্র-গর্জনে প্রবাহিত দ্রুতগতি স্রোতস্বিনী, কোথাও দিগন্ত-বিসারী প্রান্তর শীতকালে শ্বেতবর্ণ ধারণ করেছে  বরফের চাদরে, গ্রীষ্মকালে ধূসরাভ হয়েছে লাবণিক ক্ষারের ধুলোয়। সব কিছুর সংমিশ্রণ প্রতিক্রিয়া কিন্তু একটাই–যুগ যুগ ধরে অনুর্বরতা, অতিথিবিমুখতা আর দারুণ দুর্বিপাককে জিইয়ে রেখে পুরো অঞ্চলটিকে অনধিগম্য রাখা।\n\nনিরাশার এই দেশে বাসিন্দা কেউ নেই। কিছু কিছু পনি আর ব্ল্যাক ফিট মাঝে মাঝে অন্য জমিতে চরতে এদিকে আসে বটে, কিন্তু দুরন্ত সাহসীরাও বুক কাঁপানো এই প্রান্তরের সীমানা ছাড়িয়ে আসতে পারলে খুশি হয় এবং নিজেদের তৃণভূমিতে ফিরে গিয়ে হাঁফ ছেড়ে বাঁচে। ছোটো ছোটো ফাঁকা ফাঁকা গাছ আর ঝোঁপের মধ্যে হিলহিলে দেহে নিঃশব্দে সঞ্চরণ করে কেবল নেকড়ে, বড়ো বড়ো ডানার লম্বা লম্বা ঝাঁপটায় বাতাস চঞ্চল করে ওড়ে বুজার্ড শকুন, আর গভীর সংকীর্ণ গিরিসংকটে হেলেদুলে টহলদার বিরাটদেহী বিরাটকার ধূসর গ্রিজলি ভালুকরা যা পায় তাই খুঁটে খায়। এরাই এই বিজন্মভূমির একমাত্র অধিবাসী।\n\n\nসিয়েরা ব্লাঙ্কোর উত্তর সানুপ্রদেশ থেকে যে-দৃশ্য চোখে পড়ে, তার চেয়ে নিরানন্দ বিষণ্ণ দৃশ্যপট আর কোথাও আছে কিনা সন্দেহ। বিস্তীর্ণ চ্যাটালো প্রান্তরের যতদূর পর্যন্ত চোখ যাবে, দেখা যাবে কদাকার জড়পিণ্ডের মতো তাল তাল বামনাকার চ্যাপারাল ঝোপ–সব কিছুর ওপর ছোপ ছোপ ক্ষার ধুলোর দাগ। দিগন্ত যেখানে শেষ, সেই প্রত্যন্ত প্রদেশে বরফ ছাওয়া। খোঁচা খোঁচা পাহাড়ের চুড়া। সুবিশাল এই তেপান্তরের মাঠে জীবনের চিহ্ন নেই, জীবন পদবাচ্য কোনো কিছুর লক্ষণ নেই। ইস্পাত নীল স্বর্গে নেই কোনো বিহঙ্গম, ধূসর ম্যাটমেটে মর্তে নেই কোনো সঞ্চরণ, সব কিছুর ওপর রয়েছে কেবল অখণ্ড নৈঃশব্দ। কান পেতে শুনলেও অদ্ভুত সেই বিজন প্রদেশে ক্ষীণতম শব্দটিও ভেসে আসে না করন্ধ্রে, নৈঃশব্দ ছাড়া কিছু নেই–পরিপূর্ণ এবং রক্ত জল করা নৈঃশব্দ্য।\n\nবিশাল এই প্রান্তরে জীবন পদবাচ্য কিছু নেই আগে বলা হয়েছে। কথাটা পুরো সত্য নয়। সিয়েরা ব্লাঙ্কোর ওপর থেকে দেখা যায় একটা সরু পথ মরুভূমির মধ্যে ঢুকে এঁকেবেঁকে অনেক দূর গিয়ে হারিয়ে গিয়েছে শেষকালে। এ-পথ সৃষ্টি হয়েছে গাড়ির চাকার দাগ আর বহু দুঃসাহসী অভিযাত্রীর পদক্ষেপে। মাঝে মাঝে দেখা যায় সূর্যের আলোয় কী যেন ঝকঝক করছে ধূসর লাবণিক ক্ষারপের মধ্যে অতি প্রকট হয়ে রয়েছে। কাছে যান, দেখুন কী জিনিস। হাড় : কিছু বড়ো এবং ভুল কিছু ছোটো এবং সূক্ষ্ম। বড়ো অস্থি বলদের, ছোটো অস্থি মানুষের। পনেরো মাইল পর্যন্ত এই বিকট অস্থি্যুপ চোখে পড়বেই ইতস্তত বিক্ষিপ্ত অবস্থায়। গাড়ি নিয়ে মরু অভিযাত্রীদের পথটিও চেনা যাবে। এই পথে চলতে চলতেই পূর্ববর্তীরা শেষ নিশ্বাস ত্যাগ করেছে পথের পাশে।\n\nআঠারো-শো সাতচল্লিশ সালের চৌঠা মে হৃৎকম্পকারী এই ভয়াবহ দৃশ্যের পানে তাকিয়ে দাঁড়িয়ে ছিল নিঃসঙ্গ একজন পর্যটক। আকৃতি দেখে মনে হচ্ছে হয় সে ধীমান-শ্রেষ্ঠ পুরুষ, নয়তো পাণ্ডববর্জিত এই অঞ্চলের কোনো দানব। সূক্ষ্মভাবে নিরীক্ষণ করেও বলা শক্ত বয়সটা চল্লিশের কাছে, না ষাটের কাছে। মুখ শীর্ণ এবং উদ্ৰান্ত। বাদামি পার্চমেন্ট-সদৃশ্য চামড়া চেপে বসে আছে ঠেলে বেরিয়ে আসা হাড়ের ওপর; দীর্ঘ বাদামি চুল আর দাড়ির মধ্যে উঁকি দিচ্ছে পাকাচুলের শুভ্র রেখা। দুই চক্ষু কোটরাপ্রবিষ্ট কিন্তু জ্বলন্ত, অস্বাভাবিক দ্যুতিতে সমুজ্জ্বল; যে-হাতে রাইফেল আঁকড়ে আছে সেটি কঙ্কাল দেহের চাইতে বেশি মাংসল নয়। সে দাঁড়িয়ে আছে আগ্নেয়াস্ত্রের ওপর ভর দিয়ে, যষ্টি ছাড়া দাঁড়াবার ক্ষমতা যেন নেই–তা সত্ত্বেও তার চওড়া হাড়ের বিপুল কাঠামো আর দীর্ঘ দেহের মধ্যে প্রকট হয়েছে তারের মতো মাংসপেশিবহুল প্রচণ্ড গড়ন পেটন। কৃশ মুখ আর শুষ্ক অঙ্গপ্রত্যঙ্গের উপর থলির মতো চাপানো ভিন্ন পরিধেয়র মধ্যেই অবশ্য সুস্পষ্ট হয়েছে তার জরাগ্রস্ত এবং বুড়োটে আকৃতি। লোকটা মরতে চলেছে–ক্ষুধায় এবং তৃষ্ণায়।\n\n\nঅনেক যন্ত্রণার মধ্যে দিয়ে অতি কষ্টে গিরিসংকট পেরিয়ে সে এই উচ্চতায় আরোহণ করেছিল জল পাওয়ার বৃথা আশায়। কিন্তু এখন তার চোখে বিস্তৃত সুবিশাল লাবণিক প্রান্তর, বর্বর পর্বতমালার দূরবর্তী বলয় গাছপালা আগাছা ঝোঁপের চিহ্নমাত্র নেই কোথাও, নেই আর্দ্রতার ক্ষীণতম আভাস। বিশাল এই নিসর্গ দৃশ্যে আশার তিলমাত্র ঝলকও নেই কোথাও। বন্য জিজ্ঞাসু দৃষ্টি মেলে বার বার সে তাকিয়েছে উত্তরে এবং পূর্বে এবং পশ্চিমে বারংবার এসেছে সেই একই উপলব্ধি : পর্যটন অন্তে পৌঁচেছে এবড়োখেবড়ো এই খাড়া পাহাড়েই মরতে হবে তাকে। একটা বিরাট আলগা পাথরের ছায়ায় বসে বিড়বিড় করে বললে নিজের মনে–মন্দ কী! আরও বিশ বছর পরে তুলোর বিছানায় মৃত্যুর বদলে না হয় এই মৃত্যুকেই বরণ করা যাক হাসিমুখে।\n\nপাথরের ছায়ায় বসবার আগে সে অকেজো রাইফেলের বোঝা নামিয়ে রাখল পায়ের কাছে, সেইসঙ্গে ডান কাঁধে ঝোলানো ধূসর শালকাপড়ের একটা মস্ত পুটুলি। কাহিল শরীরের পক্ষে পুঁটুলিটা নিশ্চয় অতিরিক্ত ভারী, কেননা কাঁধ থেকে নামানোর সময়ে তা দমাস করে খসে পড়ল জমির ওপর। সঙ্গেসঙ্গে ধূসর পুলিন্দার মধ্যে থেকে ভেসে এল সরু গলায় গোঙানি, ঠেলে বেরিয়ে এল অতিশয় উজ্জ্বল বাদামি চোখ সমন্বিত একটা ছোট্ট ভয়ার্ত মুখ এবং ডোরাকাটা টোল খাওয়া একজোড়া খুদে মুষ্টি।\n\nকচি গলায় জাগ্রত হল ভৎসনা—\n\nউঃ! বড্ড লেগেছে!\n\nইচ্ছে করে লাগাইনি রে! অনুতপ্ত সুরে বলল লোকটা! বলতে বলতে ধূসর শালের ভাঁজ খুলে বাইরে টেনে আনল বছর পাঁচেকের ভারি মিষ্টি চেহারার ছোট্ট একটি মেয়েকে : সূক্ষ্ম রুচিসম্পন্ন পরিপাটি জুতো, স্মার্ট গোলাপি ফ্রকের ওপর পুঁচকে অ্যাপ্রনের মধ্যে রয়েছে মাতৃস্নেহের সুকোমল নিদর্শন। অবসন্ন পার হলেও মেয়েটির হাত পায়ের লাবণ্য দেখে বোঝা যায় সঙ্গী পুরুষের মতো ধকল তাকে সইতে হয়নি।\n\n\nএখন কীরকম বুঝছিস? উদবিগ্ন স্বরে শুধোয় লোকটি। কেননা মেয়েটি তখনও হাত বুলোচ্ছে মাথার পেছনে দড়ির মতো গুচ্ছ পাকানো সোনালি চুলের রাশিতে।\n\nচুম দাও, তাহলেই সেরে যাবে। অতীব গম্ভীর মুখে আহত জায়গাটা বাড়িয়ে দিয়ে বলে খুদে মেয়ে, মা-ও তাই করত। মা কোথায়?\n\nচলে গেছে। শিগগিরই দেখা হবে মনে হয় তোর সঙ্গে।\n\nচলে গেছে! কী আশ্চর্য। যাবার সময়ে আসছি বলে গেল না। মাসিমার কাছে চা খেতে গেলেও বলে আসছি আর আজকে নিয়ে তিন দিন হল মা কোথায় গেছে। বড্ড শুকনো জায়গা তো। জলটল নেই? খাবার?\n\nকিছুই নেই মা। একটু ধৈর্য ধর, সব ঠিক হয়ে যাবে। আমার কাঁধে এইভাবে মাথাটা রাখ, গায়ে জোর পাবি, ঠোঁট শুকিয়ে শুকনো চামড়ার মতো হলে কথা বলা যায় না, তাহলেও তোকে সব বলব। হাতে কী রে?\n\nকী সুন্দর জিনিস। কী ভালোই না লাগছে দেখতে! সোৎসাহে দু-টুকরো চকচকে অভ্র তুলে দেখিয়ে বলল মেয়েটি, বাড়ি গিয়ে বব-ভাইকে দোব।\n\nএর চাইতে ভালো জিনিস শিগগিরই দেখতে পাবি মা, প্রত্যয়ের সুরে বললে লোকটা! একটু অপেক্ষা কর। তার আগেই অবশ্য সব বলছি–নদী ছাড়িয়ে এলাম কখন মনে আছে তো?\n\nহ্যাঁ, আছে।\n\n\nতখন ভেবেছিলাম শিগগির আর একটা নদী পেয়ে যাব। কিন্তু কম্পাস অথবা ম্যাপে কোথাও একটা ভুল ছিল। নদী আর পেলাম না। জল ফুরিয়ে গেল। তোর জন্যে রইল শুধু কয়েক ফোঁটা। তারপর… তারপর…\n\nচান করবার জল আর পেলে না, তাই তো? গম্ভীরভাবে সঙ্গী পুরুষের ধূলিধূসরিত আকৃতির পানে তাকিয়ে বললে মেয়েটি।\n\nখাবার জলও পেলাম না। তাই প্রথমেই গেলেন মি. বেনডার, তারপরে মিসেস ম্যাকগ্রেগর, তারপর জনি হোন্স, তারপরে তোর মা।\n\nতাহলে মা-ও মরে গেছে, ফ্রকে মুখ গুঁজে ফুঁপিয়ে কেঁদে ওঠে মেয়েটি।\n\nহ্যাঁ, মা। সবাই গেছে, তুই আর আমি বাদে। তখন ভাবলাম এদিকে এলে হয়তো জল পাব। কাঁধে ঝুলিয়ে নিলাম তোকে অনেক কষ্টে এলাম বটে কিন্তু জল পাওয়া যাবে বলে মনে হচ্ছে না। বাঁচবার সম্ভাবনা বিশেষ নেই।\n\nতাহলে কি আমরাও মরে যাব? কান্না থামিয়ে অশ্রু আঁকা মুখ তুলে শুধোয় মেয়েটি।\n\nহ্যাঁ, মা, সেইরকমই মনে হচ্ছে।\n\nআগে বলোনি কেন? হাসিতে কলকলিয়ে ওঠে খুদে পরি। এমন ভয় দেখাচ্ছিলে। মরলেই তো মায়ের কাছে যাব।\n\nতা যাবি।\n\nতুমিও যাবে। মাকে বলবখন আমার জন্যে তুমি কত কী করেছ। দেখবে, স্বর্গের দরজায় এক জগ জল আর এক ঝুড়ি কেক নিয়ে মা দাঁড়িয়ে থাকবে। দু-দিক সেঁকা কেক–আমি আর বব যা খেতে ভালোবাসি। আর কত দেরি?\n\n\nজানি না–খুব দেরি নেই মনে হচ্ছে। উত্তর দিগন্তে দৃষ্টি নিবদ্ধ রেখে বললে লোকটা। স্বর্গের নীল খিলেনে তিনটে বিন্দু দেখা দিয়েছে এবং প্রতি মুহূর্তে আকারে বৃদ্ধি পাচ্ছে দ্রুতবেগে এগিয়ে আসার দরুন। দেখতে দেখতে কাছে এসে গেল কালো বিন্দু তিনটি। দেখা গেল তিনটে বিশাল বাদামি পাখি অভিযাত্রীদের মাথার ওপর চক্রাকারে পাক দিয়ে গিয়ে বসল অদূরে উঁচু পাথরে–নজর রইল কিন্তু এদের দিকেই। পাখিগুলো বুজার্ড শকুন–এরা আসা মানেই বুঝতে হবে মৃত্যুও আসছে।\n\nকদাকার পাখিগুলো দেখিয়ে ফুর্তি উচ্ছল কণ্ঠে বললে মেয়েটা, মুরগি না মোরগ? ভগবান কি এ-দেশটাও তৈরি করেছে?\n\nকরেছে বই কী, অপ্রত্যাশিত এই প্রশ্নে চমকে গিয়ে বলে লোকটি।\n\nভগবান ইলিনয় তৈরি করেছে, মিসৌরী তৈরি করেছে। আমার মনে হয় এই দেশটা অন্য কেউ তৈরি করেছে। মোটে ভালো হয়নি। জল দিতে ভুলে গেছে, গাছ বানাতে ভুল গেছে।\n\nভগবানকে ডাকলে হয় না?\n\nএখনও রাত হয়নি।\n\nতাতে কিছু এসে যাবে না। অসময়ে প্রার্থনা করলেও ভগবান কিছু মনে করবে না। প্রান্তর পেরিয়ে আসার সময়ে তুই তো রোজ রাত্রে গাড়ির মধ্যে প্রার্থনা করতিস।\n\nতুমি করো না।\n\nমনে থাকলে তো করব। সব ভুলে গেছি। ভগবানকে ডাকবার সময়ও পাইনি, যা কষ্ট গেছে। তুই বল। আমি শেষের দিকে গলা মিলাব।\n\n\nতাহলে আমার মতো তোমাকেও হাঁটু গেড়ে এইভাবে বসতে হবে, শালটা জমির ওপর বিছোতে বিছোতে বলে মেয়েটা। দু-হাত রাখবে এইভাবে। খুব ভালো লাগবে।\n\nঅদ্ভুত সেই দৃশ্য দেখবার জন্যে বুজার্ড শকুন ছাড়া আর কেউ ছিল না সেখানে। সরু শালের ওপর পাশাপাশি হাঁটু গেড়ে বসেছে দু-জন ভ্ৰামণিক একজন একটা পুঁচকে বাচাল শিশু, আর একজন বেপরোয়া পোড় খাওয়া দুঃসাহসী। একজনের মুখ চাব মাছের মতো গোলগাল আর একজনের মুখ ঝডোকাকের মতো মোটা মোটা হাড়গুলোই কেবল ঠেলে আছে–মাংস তেমন নেই। দুটো মুখই উথিত নির্মেঘ সুনীল স্বর্গ অভিমুখে বীভৎস পরিণতির সম্মুখীন হওয়ায় আন্তরিক অনুনয় পরিস্ফুট দুটি মুখেই সম্মিলিত কণ্ঠেও ধ্বনিত হচ্ছে সেই অনুনয়–সরু আর স্পষ্ট, গভীর আর রুক্ষ। দুটো গলার অন্তর থেকে ক্ষমা আর করুণা প্রার্থী দুটি অসহায় প্রাণী। প্রার্থনা শেষ হল। রক্ষকের প্রশস্ত বুকে মাথা রেখে পাথরের ছায়ায় ঘুমিয়ে পড়ল বাচ্চা। ঘুমন্ত শিশুর দিকে কিছুক্ষণ অনিমেষে চেয়ে রইল রক্ষক। কিন্তু প্রস্তুতির ডাক আর এড়াতে পারল না। তিন দিন তিন রাত সে ঘুমোয়নি, জিরোয়নি। ক্লান্ত চক্ষুর ওপর আস্তে আস্তে নেমে এল চোখের পাতা, একটু একটু করে মাথা ঝুলে এল বুকের ওপর। তারপর এক সময়ে তার ধূসরবর্ণ দাড়ির জট একাকার হয়ে মিশে গেল শিশুর স্বর্ণবর্ণ আলোকগুচ্ছের সাথে। স্বপ্নহীন সুগভীর নিদ্রায় তলিয়ে গেল দু-জনেই।\n\nপুরুষ ভ্ৰামণিক আরও আধঘণ্টা জাগ্রত থাকলে দেখতে পেত অদ্ভুত একটা দৃশ্য। ক্ষারপ্রান্তরের প্রত্যন্ত কিনারায় অনেক দূরে ধুলো ছিটিয়ে উঠল অতি সামান্য। প্রথমে খুবই অল্প। দূরের কুহেলি থেকে তা আলাদা করা যায় না। কিন্তু একটু একটু করে উপরে উঠে ছড়িয়ে পড়ল ধুলোর ফোয়ারা–আস্তে আস্তে রূপ নিল মেঘের। ধুলোর মেঘ। স্পষ্ট, নিরেট ধুলোর মেঘ। ক্রমশ বেড়েই চলল মেঘের আকার। শেষকালে যে-আকারে পৌঁছোল তাতে স্পষ্ট বোেঝা গেল অগুনতি প্রাণীর পদক্ষেপের ফলেই সৃষ্টি এই ধূলি মেঘের। উর্বর জায়গা হলে মনে হত তৃণভূমিতে চরতে বেরিয়েছে পালে পালে বাইসন মোষ। কিন্তু এই অনুর্বর অঞ্চলে তা একেবারেই অসম্ভব। সমাজচ্যুত এই দুটি প্রাণী যে নিঃসঙ্গ খাড়া পাহাড়ের গায়ে গভীর ঘুমে আচ্ছন্ন, ধুলোর ঘূর্ণিমুখ সেইদিকে আরও এগিয়ে আসার পর ঝটিকার মধ্যে একটু একটু করে উঁকি দিল ক্যানভাস-ছাওয়া ঘোড়ায় টানা গাড়ির শীর্ষদেশ এবং সশস্ত্র ঘোড়সওয়ারদের মূর্তি। প্রেতচ্ছায়ার মতো সেই দৃশ্য আরও স্পষ্ট হল। মরুযাত্রীদের একটা বিরাট দল চলেছে বসবাসের উপর্যুক্ত ঢাকা ঘোড়ার গাড়ি নিয়ে। চলেছে পশ্চিমদিকে। কী বিরাট সেই দল! সামনের গাড়িগুলো পাহাড়ের সন্নিদেশে পৌঁছে গেলেও পেছন দিক তখনও অদৃশ্য রইল দূরদিগন্তে। বিপুল মরুপ্রান্তরের ওপর বিস্তৃত রইল কেবল ঢাকা গাড়ি আর খোলা গাড়ি, ঘোড়ার পিঠে পুরুষ, পায়ে হাঁটা পুরুষ। অগণিত মেয়ে পিঠে বোঝা নিয়ে নুয়ে পড়ে ছুটছে গাড়ির পাশে পাশে। বাচ্চারাও পাশে, সাদা আবরণ সরিয়ে উঁকি দিচ্ছে গাড়ির ভেতরে। সাধারণ আদিবাসী এরা নয়, বিশেষ ধরনের যাযাবর মানুষ অবস্থায় চাপে পড়ে বাধ্য হয়ে নতুন দেশের সন্ধানে বেরিয়েছে। বাতাসে ভাসছে অনেকরকম আওয়াজের মিশ্রিত কোলাহল। গাড়ির চাকার গড়গড়ানি, বহু মানুষের একটা চাপা গুমগুম আওয়াজ, তৈলহীন চাকার ক্যাঁচ ক্যাঁচ শব্দ আর অগুনতি ঘোড়ার হেষারব। এত আওয়াজেও কিন্তু পথ শ্রান্ত দুই অভিযাত্রীর ঘুম ভাঙল না খাড়া পাহাড়ের গায়ে।\n\n\nমরুযাত্রীদের পুরোভাগে জনাবিশেক অশ্বারোহী আসছে। গম্ভীর আর লোহার মতো শক্ত মুখ প্রত্যেকের। পরনে সাদাসিদে হাতে বোনা পোশাক। কাঁধে রাইফেল। খাড়া পাহাড়ের তলদেশে এসে ঘোড়া দাঁড় করিয়ে যুক্তি পরামর্শ শুরু করল নিজেদের মধ্যে।\n\nচুল যার ধূসর, গোঁফদাড়ি নিখুঁতভাবে কামানো, ঠোঁট কঠিন–সে বললে, ব্রাদার, কুয়োগুলো কিন্তু ডান দিকে।\n\nআরেকজন বললে, সিয়েরা ব্লানকোর ডান দিকে–তাহলেই পৌছাবো রিও গ্রান্ডি।\n\nজলের জন্যে ঘাবড়িয়ো না, চিৎকার শোনা গেল তৃতীয় কণ্ঠে।পাথর ছুঁড়ে যিনি ফোয়ারা বার করতে পারেন, এ দুঃসময়ে মুখ তুলে তিনি চাইবেনই, আমরা যে তার নির্বাচিত সন্তান।\n\nতাই হোক! তাই হোক! সম্মিলিত কণ্ঠে সাড়া দিল পুরো দলটা।\n\nএই বলে ফের যাত্রা শুরু করতে যাচ্ছে মরুযাত্রীদের পুরোধাগণ, এমন সময়ে খোঁচা খোঁচা খাড়াই পাহাড়ের দিকে তাকিয়ে সবিস্ময়ে চেঁচিয়ে উঠল একজন। চোখ তার সবচেয়ে তীক্ষ্ণ্ণ, বয়স সবচেয়ে কম। তাই সে দেখতে পেয়েছে অনেক উঁচুতে ধূসর কঠিন পাথরের পটভূমিকায় সামান্য একটু গোলাপি রং। হাওয়ায় পতপত করে উড়ছে জিনিসটা। ধূসর পাহাড়ের গায়ে বড়ো উজ্জ্বলভাবে দেখাচ্ছে গোলাপি গুচ্ছ। দৃশ্যটা চোখে পড়ার সঙ্গেসঙ্গে লাগাম টেনে দাঁড়িয়ে গেল প্রত্যেকে, কাঁধের রাইফেল চলে এল হাতে, পেছন থেকে আরও সশস্ত্র ঘোড়সওয়ার ছুটে এল পুরোধাদের বলীয়ান করতে। মুখে মুখে শোনা গেল একটাই শব্দ–লাল চামড়া।\n\nদলপতি বলে যাকে মনে হল, তার বয়স হয়েছে। বললেন, ইন্ডিয়ানরা এখানে সংখ্যায় বেশি নেই। পনিদের পেরিয়ে এসেছি। বড়ো পাহাড় না-আসা পর্যন্ত আদিবাসীদের তো আর দেখা যাবে না।\n\n\nএকজন বললে, ব্রাদার স্টানজারসন, গিয়ে দেখে আসব?\n\nআমি যাব, আমি যাব, চেঁচিয়ে উঠল ডজনখানেক কণ্ঠ।\n\nবয়স্ক ব্যক্তি বললেন, ঘোড়া রেখে যাও। তৎক্ষণাৎ ঘোড়া থেকে লাফিয়ে নেমে, পাথরের গায়ে লাগাম বেঁধে তরুণ যাযাবররা খাড়াই পাহাড় বেয়ে উঠতে লাগল কৌতূহল মিটোনোর অভিলাষে। উঠতে লাগল নিঃশব্দে দ্রুতবেগে, অত্যন্ত স্কাউটের দক্ষতা আর আত্মবিশ্বাস নিয়ে। নীচ থেকে ঘাড় বেঁকিয়ে সঙ্গীরা দেখলে পাথর থেকে পাথরের গায়ে লাফিয়ে লাফিয়ে উঠছে তরুণ দল। দেখতে দেখতে যেন আকাশের কাছে পৌঁছে গেল দেহরেখাগুলো। গোলাপিগুচ্ছ দেখে প্রথমে যে চেঁচিয়েছিল, পথ দেখিয়ে নিয়ে চলেছে সেই তরুণটি। অনুবর্তী সঙ্গীরা অবাক হল হঠাৎ তার সবিস্ময়ে শূন্যে দু-হাত নিক্ষেপ দেখে। কাছে যাওয়ার পর কিন্তু প্রত্যেকেই একইভাবে দু-হাত শূন্যে ছুঁড়ে লাফিয়ে উঠল প্রচণ্ড বিস্ময়ে। দেখল সেই একই দৃশ্য।\n\nন্যাড়া পাহাড়ের মাথাটা চ্যাটালো। ছোট্ট উপত্যকার মাঝে একটিমাত্র দানবিক পাথর। পাথরের গায়ে হেলান দিয়ে এলিয়ে রয়েছে দীর্ঘকায় এক পুরুষ, দাড়ি বেশ লম্বা, রুক্ষ কদাকার মূর্তি, কিন্তু অতিরিক্ত মাত্রায় বিশীর্ণ। প্রশান্ত মুখে ঘুমোচ্ছে সে, নিশেস পড়ছে নিয়মিত ছন্দে। পাশেই ঘুমোচ্ছে একটি শিশু। সুগোল, সাদা হাতে জড়িয়ে রয়েছে পুরুষ-সঙ্গীর সিটে-মারা শক্ত বাদামি ঘাড়, স্বর্ণকেশ মাথাটি ন্যস্ত বুকের মখমল-পোশাকে। দ্বিধাবিভক্ত গোলাপি অধরোষ্ঠের ফাঁক দিয়ে দেখা যাচ্ছে সাদা দাঁতের সুসম সারি, শিশুমুখে ভাসছে বড়ো ফুর্তির হাসি যেন ঘুমিয়ে ঘুমিয়েও সে খেলায় মত্ত। ছোট্ট ফুলো পা দুটিতে সাদা মোজা, পরিচ্ছন্ন জুতোয় চকচকে বাক। সঙ্গীর দীর্ঘ শুকনো কুঁচকোনো হাত-পায়ের পাশে সে-দৃশ্য বড়োই বেমানান। বিরাট পাথরটার ওপরের কিনারায় নীরবে বসে তিনটে বুজার্ড শকুনি একদৃষ্টে চেয়ে ছিল ঘুমন্ত এই দুই মূর্তির পানে। আগন্তুকদের দেখে কর্কশ নৈরাশ্য চিৎকারে বাতাস ফালাফালা করে ডানা ঝটপটিয়ে উড়ে গেল দিগন্তে।\n\nবিকট পক্ষীদের রক্ত-জল-করা ওই চিৎকারেই ঘুম ভেঙে গেল ঘুমন্ত দু-জনের। ফ্যালফ্যাল করে হতভম্ব মুখে চাইল চারদিকে। পুরুষটি টলতে টলতে উঠে দাঁড়িয়ে দৃষ্টি নিক্ষেপ করল দিগন্ত বিস্তৃত ধু-ধু প্রান্তরের দিকে। ঘুমের আগে এই প্রান্তর ছিল নিষ্প্রাণ, নিথর নির্জন। এখন সেখানে পিলপিল করছে মানুষ আর পশু। নিজের চোখকেই যেন বিশ্বাস করতে পারল না লোকটা, বিষম অবিশ্বাস ফুটে উঠল চোখে-মুখে, শিরা-বার-করা দু-হাত দিয়ে রগড়ে নিল দু-চোখ। বললে বিড়বিড় কণ্ঠে এরই নাম হল মতিভ্রম। কোট খামচে ধরে পাশেই দাঁড়িয়ে বাচ্চা মেয়েটি। মুখে কথা নেই, কিন্তু শিশুসুলভ সপ্রশ্ন চোখে অবাক হয়ে দেখছে আশেপাশের দৃশ্য।\n\nউদ্ধারকারী দলটি অবশ্য অচিরেই সমাজচ্যুত দু-জনকে বুঝিয়ে দিলে স্বপ্ন দৃশ্য নয়, মতিভ্রম নয়, সত্যি ওরা রক্তমাংসের মানুষ। একজন মেয়েটিকে কাঁধে তুলে নিলে, দু-জন বিশীর্ণ কাহিল লোকটিকে দু-পাশ থেকে ধরে নিয়ে চলল নীচে ঘোড়ার গাড়ির দিকে।\n\nযেতে যেতে বললে লোকটা, আমার নাম জন ফেরিয়ার। একুশজনের মধ্যে বেঁচে আছি। কেবল আমি আর ওই বাচ্চা মেয়েটা। খিদে তেষ্টায় মরেছে প্রত্যেকে দক্ষিণ অঞ্চলে।\n\nতোমার বাচ্চা? শুধোয় একজন।\n\nএখন থেকে তাই, জন ফেরিয়ার বললে বেপরোয়া কণ্ঠে। ওকে আমি বাঁচিয়েছি, তাই ও আমারই মেয়ে। থাকবে আমারই কোলে–ছিনিয়ে নিতে দেব না কাউকে। আজ থেকে ওর নাম লুসি ফেরিয়ার। কিন্তু তোমরা কে? সকৌতূহলে রৌদ্রদগ্ধ দীর্ঘকায় সুঠামদেহী উদ্ধারকারীদের দিকে তাকিয়ে শুধোয় জন–তোমরা দেখছি দলে বেশ ভারী।\n\nপ্রায় দশ হাজার। ঈশ্বরে নিগৃহীত সন্তান আমরা অ্যাঞ্জেল মেরোনার ধর্মে দীক্ষিত।\n\nনাম শুনিনি কখনো। তবে চ্যালাচামুণ্ডা জুটিয়েছে ভালো।\n\nইস্পাত-কঠিন কণ্ঠে তৎক্ষণাৎ জবাব দিল একজন তরুণ, পবিত্র প্রসঙ্গ নিয়ে রঙ্গ পরিহাস–করলেই খুশি হব। পালমিরার ধর্মপ্রাণ জোসেফ স্মিথকে একটা পেটাই সোনার পাত দেওয়া হয়েছিল। মিশরীয় হরফে তাতে যে-বাণী উৎকীর্ণ ছিল, আমরা তার প্রতিটি অক্ষর মেনে চলি। বেদবাক্যের মতোই তা পবিত্র আমাদের কাছে। আমরা আসছি ইলিনয় প্রদেশের নভু অঞ্চল থেকে মন্দির প্রতিষ্ঠাও করেছি সেখানে। ঈশ্বর প্রসাদে বঞ্চিত অত্যন্ত উগ্র প্রকৃতির এক ব্যক্তির অত্যাচারে আমরা দেশ-ছাড়া হয়ে খুঁজছি এমন একটা দেশ যেখানে উগ্রতা নেই, বর্বরতা নেই–সে-দেশ মরুভূমির মাঝে হলেও আপত্তি নেই।\n\nনভু নামটা ঘা দিয়েছিল জন ফেরিয়ারের স্মৃতির তন্ত্রীতে। বললে, তাই বলো। তোমরা মর্মোন।\n\nহ্যাঁ, আমরা মর্মোন, একবাক্যে একসঙ্গে বলে উঠল সবকটি তরুণ।\n\nযাচ্ছ কোথায়?\n\nজানি না। ঈশ্বর আমাদের পথ দেখিয়ে নিয়ে চলেছেন অবতারের মাধ্যমে। আমাদের সঙ্গে চলেছেন অবতার। তোমাকেও যেতে হবে তার সামনে। তিনিই ব্যবস্থা দেবেন তোমার ব্যাপারে!\n\nএসে গেছে সানুদেশ। ঘিরে ধরেছে তীর্থযাত্রীরা; ফ্যাকাশে মুখ, বিনম্র স্ত্রীলোক। স্বাস্থ্যোজ্জ্বল হাস্যমুখের ছেলে-মেয়ে; উদবিগ্ন, ব্যগ্র-চক্ষু পুরুষ। একজনের কচি বয়স আর একজনের দুরবস্থা দেখে আহা আহা সহানুভূতিতে বাতাস মুখরিত। উদ্ধারকারীরা ঠেলেঠুলে এদের মাঝ দিয়ে দুজনকে নিয়ে গিয়ে দাঁড়াল ছিমছাম চেহারার একটা বড়ো আকারের গাড়ির সামনে। বেশ সাজানো ওয়াগন। অন্যান্য ওয়াগনে দুটো কি চারটে ঘোড়া, কিন্তু বিশেষ এই ওয়াগনটি টানছে ছ-টি ঘোড়া। চালকের পাশে আসীন পুরুষটি বয়সের দিক দিয়ে বড়োজোর তিরিশ হলেও প্রকাণ্ড মাথা আর দৃঢ় মুখচ্ছবি দেখে নেতা বলেই মনে হয়। বাদামি মলাট দেওয়া বই পড়ছিল পুরুষটি। এরা গিয়ে দাঁড়াতে বই নামিয়ে মন দিয়ে শুনল সব কথা। তারপর চোখ তুলল সমাজচ্যুত দু-জনের দিকে।\n\nবললে, ধীর, গম্ভীর, শান্ত গলায়, আমার সঙ্গে আসতে হলে আমরা যে-ধর্মে বিশ্বাসী, সেই বিশ্বাস আনতে হবে। নেকড়ের সঙ্গে পথ চলতে আমরা চাই না। ছোট্ট পোকাই শেষ পর্যন্ত পচন ধরায় গোটা ফলে। তার চাইতে তোমাদের হাড় মরুভূমিতে ফেলে যেতেও আমরা তৈরি এই শর্তে যদি আসতে চাও আসতে পার।\n\nযেকোনো শর্তেই আসতে রাজি, প্রাণঢালা আবেগে বলল জন ফেরিয়ার। মুচকি হাসল বয়স্কা। অবিচল রইল নেতার নির্বিকার, কঠোর মুখভাব।\n\nবলল, ব্রাদার স্ট্যানজারসন, সঙ্গে নাও এদের! খাওয়াদাওয়ার ব্যবস্থা করো–বাচ্চাটাকে দেখো। পবিত্র ধর্মতত্ত্ব বুঝিয়ে দিয়ে অবসর মতো। আর দেরি নয়। চলো এগিয়ে চলো জিয়ন!\n\nচলো জিয়ন! গলা মিলিয়ে হাঁক দিল মর্মোনরা। মুখে মুখে ফিরতে লাগল সেই ডাক–চলো জিয়ন! চলো জিয়ন! চলো জিয়ন! দূর হতে দূরে ছড়িয়ে গেল সেই হাঁক আস্তে আস্তে ক্ষীণ গুঞ্জন ধ্বনির মতো মিলিয়ে গেল দূর দিগন্তে। চাবুকের সপাং সপাং আওয়াজ আর ক্যাঁচ ক্যাঁচ চক্ৰধ্বনির মধ্যে দিয়ে নতুন করে শুরু হল বিরাট বিরাট ওয়াগনগুলোর পথ চলা। দেখতে দেখতে বিশাল ক্যারাভানটা সর্পিল ভঙ্গিমায় এগিয়ে চলল মরুপথ বেয়ে। নবাগত দু-জনকে এক ওয়াগনে নিয়ে এল একজন বয়স্ক পুরুষ পরিচর্যার ভার পড়েছে এর ওপরেই। এসে দেখল খাবার তৈরি।\n\nবলল, এখানেই থাক এখন। দু-দিনেই ক্লান্তি কেটে যাবে। কিন্তু মনে রেখো, এই মুহূর্ত থেকে তুমি আমাদের একজন একই ধর্মে বিশ্বাসী। ব্রিগহ্যাম ইয়ং যা বলেছেন, তার নিজের কথা নয়–জোসেফ স্মিথের কণ্ঠে বললেন স্বয়ং ঈশ্বর।"}];
